import assert from "node:assert/strict";
import {Engine,memoryStore} from "../static/engine.mjs";
import * as wire from "../static/wire.mjs";
const human=await wire.newKeys(),host=await wire.newKeys();
const hp=await wire.publicEntry(human,"self/phone"),ap=await wire.publicEntry(host,"self/worker");
const first=await wire.newRoster(human,hp.address,"Owner");
const join=await wire.joinConsent(host,ap.address,first.person,1,await wire.rosterHash(first));
const linked=await wire.nextRoster(human,hp.address,first,[hp,ap],join);
await wire.verifyNext(linked,first);
const store=memoryStore();let calls=0;
const e=new Engine({store,base:"https://synthetic.invalid",fetch:async()=>{calls++;throw Error("must refuse before Hub access")}});
e.address=ap.address;e.keys=host;e.fp=await wire.fingerprint(ap);
e.me={...await e.personRecord([first,linked],"self",null),published:true};
await assert.rejects(()=>e.api("/api/device/link",{}),/human devices/);
const id=wire.newID(),expires=Math.floor(Date.now()/1000)+300;
await store.write([{s:"kv",k:"links",v:{offers:{[id]:{person:e.me.person,seq:e.me.seq,roster:e.me.hash}},requests:{[id]:{address:"self/new",expires,state:"pending"}}}}]);
await assert.rejects(()=>e.api("/api/device/decide",{id,accept:true}),/human devices/);
assert.equal(calls,0,"agent host reached enrollment Hub");
e.stop();console.log("P7 engine human gates PASS");
